import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { spawn } from "node:child_process";
import assert from "node:assert/strict";

const BOT = "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g4-3/bot.mjs";
const { reserve } = await import(BOT);
const base = await mkdtemp(path.join(tmpdir(), "bot-"));
process.env.STATE_DIR = path.join(base, "nested", "state"); // missing parents on purpose
const H = 3600e3, DAY = 24 * H;
const t0 = new Date("2026-10-23T08:00:00Z");
const at = (ms) => new Date(t0.getTime() + ms);

// 1. five mixed-channel sends allowed, 6th denied with exact retryAt
const chans = ["sms", "push", "chat", "sms", "push"];
for (let i = 0; i < 5; i++) {
  const r = await reserve("cust-1", chans[i], at(i * 60e3));
  assert.equal(r.allowed, true); assert.equal(r.retryAt, null);
}
const d = await reserve("cust-1", "chat", at(10 * 60e3));
assert.equal(d.allowed, false);
assert.equal(d.retryAt.getTime(), t0.getTime() + DAY); // oldest send (t0) + 24h
console.log("denied reason:", d.reason);

// 2. denied calls are not counted: still blocked just before retryAt, allowed at it
const before = await reserve("cust-1", "sms", new Date(t0.getTime() + DAY - 1));
assert.equal(before.allowed, false);
assert.equal(before.retryAt.getTime(), t0.getTime() + DAY);
const at_ = await reserve("cust-1", "push", d.retryAt);
assert.equal(at_.allowed, true);
// window now: sends at t0+1m..t0+4m and t0+DAY => 5 in window; next retry = t0+1m+24h
const d2 = await reserve("cust-1", "sms", new Date(t0.getTime() + DAY + 1));
assert.equal(d2.allowed, false);
assert.equal(d2.retryAt.getTime(), t0.getTime() + 60e3 + DAY);

// 3. isolation: another customer unaffected
const other = await reserve("cust-2", "sms", at(0));
assert.equal(other.allowed, true);

// 4. concurrency: 20 separate processes, same customer, same instant
const procs = Array.from({ length: 20 }, (_, i) => new Promise((resolve, reject) => {
  const p = spawn(process.execPath, ["/tmp/bot-check/worker.mjs", "cust-3", ["sms","push","chat"][i % 3], "2026-10-23T09:00:00Z"],
    { env: process.env, stdio: ["ignore", "pipe", "inherit"] });
  let out = ""; p.stdout.on("data", (c) => (out += c));
  p.on("exit", (code) => code === 0 ? resolve(JSON.parse(out)) : reject(new Error("worker exit " + code)));
}));
const results = await Promise.all(procs);
const allowedCount = results.filter((r) => r.allowed).length;
console.log("concurrent allowed:", allowedCount, "of 20");
assert.equal(allowedCount, 5);
assert.ok(results.filter((r) => !r.allowed).every((r) => r.retryAt));

// 5. invalid input rejected
await assert.rejects(reserve("", "sms", at(0)), TypeError);
await assert.rejects(reserve("x", "email", at(0)), TypeError);
await assert.rejects(reserve("x", "sms", "2026-10-23"), TypeError);

// 6. no leftover lock or temp files
const { readdir } = await import("node:fs/promises");
const files = await readdir(path.join(process.env.STATE_DIR, "users"));
assert.ok(files.every((f) => f.endsWith(".json")), files.join(","));
console.log("ALL CHECKS PASSED");
EOF
cd /tmp/bot-check && node check.mjs
